        grid_out[idx] = voxel;
        return;
    }

    // Stripe pattern: process 4-column stripes for vectorized access
    let stripe_id = x >> 2u;  // Which 4-column stripe
    let stripe_pos = x & 3u;  // Position within stripe (0-3)
    let stripe_phase = (stripe_id + y) & 3u;  // Phase for conflict resolution

    let self_thermal = get_thermal(voxel);

    // Adaptive self-weight based on position for stability
    let self_weight = 16u + (stripe_pos & 1u);
    var thermal_sum = self_thermal * self_weight;
    var weight_sum = self_weight;

    // Packed neighbor data for SIMD processing
    var neighbors_h = vec4<u32>(0u);  // horizontal: west2, west1, east1, east2
    var neighbors_v = vec4<u32>(0u);  // vertical: north2, north1, south1, south2
    var valid_h = vec4<u32>(0u);
    var valid_v = vec4<u32>(0u);

    // Horizontal neighbors with extended reach based on stripe phase
    let h_reach = select(1u, 2u, stripe_phase < 2u);

    // West neighbors
    if (x >= h_reach) {
        let west1 = grid_in[idx - 1u];
        if (get_material(west1) != MAT_AIR) {
            neighbors_h.y = get_thermal(west1);
            valid_h.y = 1u;
        }

        if (h_reach == 2u && x >= 2u) {
            let west2 = grid_in[idx - 2u];
            if (get_material(west2) != MAT_AIR) {
                neighbors_h.x = get_thermal(west2);
                valid_h.x = 1u;
            }
        }
    }

    // East neighbors
    if (x + h_reach <= GRID_WIDTH) {
        if (x < GRID_WIDTH - 1u) {
            let east1 = grid_in[idx + 1u];
            if (get_material(east1) != MAT_AIR) {
                neighbors_h.z = get_thermal(east1);
                valid_h.z = 1u;
            }
        }

        if (h_reach == 2u && x < GRID_WIDTH - 2u) {
            let east2 = grid_in[idx + 2u];
            if (get_material(east2) != MAT_AIR) {
                neighbors_h.w = get_thermal(east2);
                valid_h.w = 1u;
            }
        }
    }

    // Vertical neighbors with phase-based reach
    let v_reach = select(1u, 2u, (stripe_phase & 1u) == 0u);

    // North neighbors
    if (y >= v_reach) {
        let north1 = grid_in[idx - GRID_WIDTH];
        if (get_material(north1) != MAT_AIR) {
            neighbors_v.y = get_thermal(north1);
            valid_v.y = 1u;
        }

        if (v_reach == 2u && y >= 2u) {
            let north2 = grid_in[idx - 2u * GRID_WIDTH];
            if (get_material(north2) != MAT_AIR) {
                neighbors_v.x = get_thermal(north2);
                valid_v.x = 1u;
            }
        }
    }

    // South neighbors
    if (y + v_reach <= GRID_HEIGHT) {
        if (y < GRID_HEIGHT - 1u) {
            let south1 = grid_in[idx + GRID_WIDTH];
            if (get_material(south1) != MAT_AIR) {
                neighbors_v.z = get_thermal(south1);
                valid_v.z = 1u;
            }
        }

        if (v_reach == 2u && y < GRID_HEIGHT - 2u) {
            let south2 = grid_in[idx + 2u * GRID_WIDTH];
            if (get_material(south2) != MAT_AIR) {
                neighbors_v.w = get_thermal(south2);
                valid_v.w = 1u;
            }
        }
    }

    // Diagonal neighbors based on stripe position for conflict avoidance
    var diag_thermal = 0u;
    var diag_count = 0u;

    let process_diags = ((stripe_pos ^ stripe_phase) & 1u) == 0u;

    if (process_diags) {
        // Northwest
        if (x > 0u && y > 0u) {
            let nw = grid_in[idx - GRID_WIDTH - 1u];
            if (get_material(nw) != MAT_AIR) {
                diag_thermal = diag_thermal + get_thermal(nw);
                diag_count = diag_count + 1u;
            }
        }

        // Southeast
        if (x < GRID_WIDTH - 1u && y < GRID_HEIGHT - 1u) {
            let se = grid_in[idx + GRID_WIDTH + 1u];
            if (get_material(se) != MAT_AIR) {
                diag_thermal = diag_thermal + get_thermal(se);
                diag_count = diag_count + 1u;
            }
        }
    } else {
        // Northeast
        if (x < GRID_WIDTH - 1u && y > 0u) {
            let ne = grid_in[idx - GRID_WIDTH + 1u];
            if (get_material(ne) != MAT_AIR) {
                diag_thermal = diag_thermal + get_thermal(ne);
                diag_count = diag_count + 1u;
            }
        }

        // Southwest
        if (x > 0u && y < GRID_HEIGHT - 1u) {
            let sw = grid_in[idx + GRID_WIDTH - 1u];
            if (get_material(sw) != MAT_AIR) {
                diag_thermal = diag_thermal + get_thermal(sw);
                diag_count = diag_count + 1u;
            }
        }
    }

    // Vectorized thermal accumulation with distance-based weights
    let weights_h = vec4<u32>(1u, 2u, 2u, 1u);  // Closer neighbors weighted more
    let weights_v = vec4<u32>(1u, 2u, 2u, 1u);

    let h_contribution = dot(neighbors_h * valid_h, weights_h);
    let v_contribution = dot(neighbors_v * valid_v, weights_v);
    let h_weight = dot(valid_h, weights_h);
    let v_weight = dot(valid_v, weights_v);

    thermal_sum = thermal_sum + h_contribution + v_contribution + diag_thermal;
    weight_sum = weight_sum + h_weight + v_weight + diag_count;

    // Ensure non-zero weight
    weight_sum = max(weight_sum, 1u);

    let new_thermal = thermal_sum / weight_sum;
    grid_out[idx] = set_thermal(voxel, new_thermal);
}

